/* ---------- COASTLINES ---------------------------------
   Two land datasets as delta-encoded integer rings: the first pair is
   an absolute position, every later pair a difference, scaled by 1e4
   (bay) or 1e3 (sea). The Vesuvian shore and the Sarno plain are
   pushed back to their AD 79 line (500 m and 1 km), and the Tiber
   delta by 3 km, so that towns buried or silted since sit on the
   coast they had. OpenStreetMap for the bay, Natural Earth beyond.
   ------------------------------------------------------- */

function decodeRings(rings, scale) {
  return rings.map((r) => {
    const out = new Float64Array(r.length);
    let x = 0;
    let y = 0;
    for (let i = 0; i < r.length; i += 2) {
      x += r[i];
      y += r[i + 1];
      out[i] = x / scale;
      out[i + 1] = y / scale;
    }
    return out;
  });
}

