/* ---------- ROUTES ---------------------------------------
   Travel time is no longer typed. Each place has one or more
   candidate routes made of legs; a leg is a mode and a chain of
   waypoints. Distance along the chain is great-circle, days are
   distance over the mode's pace plus any fixed wait. The fastest
   route permitted by the season and the traveller is the one used,
   and the one drawn.
   --------------------------------------------------------- */

const PACE = {
  foot: { kmPerDay: 20, label: "on foot" },
  track: { kmPerDay: 12, label: "by mule track" },
  road: { kmPerDay: 30, label: "by road" },
  boat: { kmPerDay: 35, label: "by boat, sheltered water" },
  coast: { kmPerDay: 25, label: "by boat, exposed coast" },
  ship: { kmPerDay: 180, label: "by ship, open sea" },
  shipcoast: { kmPerDay: 110, label: "by ship, coasting" },
};
const SHIP_WAIT = 1.5; // days spent finding an open-sea passage at Puteoli
const COASTER_WAIT = 0.3; // a coaster runs often enough to be caught within the day
const SEA_MODES = new Set(["boat", "coast", "ship", "shipcoast"]);

/* Who is travelling changes which legs are available and how fast
   the land ones go. Each persona also carries defaults for what they
   are carrying and how much discomfort they will put up with; both can
   be overridden. */
const PERSONAS = {
  villa: {
    label: "Villa household",
    blurb: "Hires a boat, takes a carriage, buys passage on a ship. Travels with baggage.",
    allow: (leg, km) => true,
    pace: {},
    boarding: 0,
    shipWait: SHIP_WAIT,
    coasterWait: COASTER_WAIT,
    load: "pack",
    tolerance: "delicate",
  },
  fisher: {
    label: "Fishing family",
    blurb: "Own boat; walks the roads; can work a passage on a ship but waits longer for a berth.",
    allow: (leg, km) => true,
    pace: { road: 25 },
    boarding: 0,
    shipWait: 4,
    coasterWait: 0.75,
    load: "mule",
    tolerance: "hardy",
  },
  tenant: {
    label: "Tenant on the terraces",
    blurb: "Walks, or waits for a lift in someone else's boat. No business on a ship.",
    allow: (leg, km) => !(leg.m === "ship" || leg.m === "shipcoast"),
    pace: { road: 25, boat: 20, coast: 15 },
    boarding: 0.15,
    shipWait: Infinity,
    coasterWait: Infinity,
    load: "pack",
    tolerance: "ordinary",
  },
};

/* The sailing year. Vegetius has the sea open from late May to
   mid-September, marginal either side, and shut from mid-November. In
   the marginal months small boats and coasters ran; nobody committed a
   laden merchantman to open water. */
const SEASONS = {
  sailing: { label: "Sailing season", blurb: "Late May to mid-September. Everything sails.", forbid: [] },
  shoulder: { label: "Shoulder months", blurb: "March to May and September to November. Boats and coasters run; no ship puts out to open sea.", forbid: ["ship"] },
  winter: { label: "Winter", blurb: "Mid-November to March. The sea is shut.", forbid: ["boat", "coast", "ship", "shipcoast"] },
};

/* What is being carried. This is physics: it changes paces and which
   legs exist, and never touches a boat. */
const LOADS = {
  none: { label: "Nothing", blurb: "", factor: {}, forbid: [] },
  /* footLimitKm: how far porters will carry it from the quay. */
  pack: { label: "A pack", blurb: "What one person carries.", factor: { foot: 0.85, track: 0.85 }, forbid: [] },
  mule: { label: "A mule-load", blurb: "A laden animal, led on foot.", factor: { foot: 0.7, track: 0.7, road: 0.9 }, forbid: [] },
  cargo: {
    label: "Cargo",
    blurb: "Amphorae, timber, stone: a cart or a hull. No cart road left Surrentum until the nineteenth century.",
    factor: { road: 0.67 },
    forbid: ["track"],
    footLimitKm: 1.5,
  },
};

/* How much discomfort the traveller will put up with. This is
   preference, not physics: it weighs the legs when choosing between
   routes, and the time shown is always the real time of the route
   chosen. The weights are invented and are shown as such. */
const TOLERANCES = {
  hardy: { label: "Hardy", blurb: "The fastest way, whatever it is.", weight: {} },
  ordinary: { label: "Ordinary", blurb: "Avoids the exposed coast and long sea passages when the alternative is close.", weight: { coast: 1.2, ship: 1.15, track: 1.15 } },
  delicate: {
    label: "Delicate",
    blurb: "Avoids exposed water, long walks and mule tracks unless the cost is large.",
    weight: { coast: 1.6, ship: 1.4, shipcoast: 1.3, track: 1.5, boat: 1.15, foot: 1.2 },
  },
};

/* Compose a traveller from a persona and its overrides. */
function makeTraveller(who, loadKey, toleranceKey) {
  const base = PERSONAS[who];
  const load = LOADS[loadKey];
  const tol = TOLERANCES[toleranceKey];
  const pace = {};
  for (const m of Object.keys(PACE)) {
    const p = base.pace[m] ?? PACE[m].kmPerDay;
    pace[m] = p * (load.factor[m] ?? 1);
  }
  return {
    ...base,
    pace,
    allow: (leg, km) => !load.forbid.includes(leg.m) && !(load.footLimitKm !== undefined && leg.m === "foot" && km > load.footLimitKm) && base.allow(leg, km),
    weight: tol.weight,
    loadKey,
    toleranceKey,
  };
}

