/* ---------- GEOMETRY --------------------------------------- */

const HOME = PLACES[0];
const R_EARTH = 6371;
const rad = (d) => (d * Math.PI) / 180;

function gcKm(lon1, lat1, lon2, lat2) {
  const dLat = rad(lat2 - lat1);
  const dLon = rad(lon2 - lon1);
  const h = Math.sin(dLat / 2) ** 2 + Math.cos(rad(lat1)) * Math.cos(rad(lat2)) * Math.sin(dLon / 2) ** 2;
  return 2 * R_EARTH * Math.asin(Math.sqrt(h));
}
function bearingDeg(lon1, lat1, lon2, lat2) {
  const dLon = rad(lon2 - lon1);
  const y = Math.sin(dLon) * Math.cos(rad(lat2));
  const x = Math.cos(rad(lat1)) * Math.sin(rad(lat2)) - Math.sin(rad(lat1)) * Math.cos(rad(lat2)) * Math.cos(dLon);
  return (Math.atan2(y, x) * 180) / Math.PI;
}
const N = (k) => NODES[k];
const kmBetween = (a, b) => gcKm(a[0], a[1], b[0], b[1]);
const nodeKm = (a, b) => kmBetween(N(a), N(b));
const fromHomeKm = (lon, lat) => gcKm(HOME.lon, HOME.lat, lon, lat);
const fromHomeBearing = (lon, lat) => bearingDeg(HOME.lon, HOME.lat, lon, lat);

/* Destination lon/lat given a start, a bearing and a distance. */
function destination(lon, lat, bearing, km) {
  const d = km / R_EARTH;
  const b = rad(bearing);
  const la1 = rad(lat);
  const lo1 = rad(lon);
  const la2 = Math.asin(Math.sin(la1) * Math.cos(d) + Math.cos(la1) * Math.sin(d) * Math.cos(b));
  const lo2 = lo1 + Math.atan2(Math.sin(b) * Math.sin(d) * Math.cos(la1), Math.cos(d) - Math.sin(la1) * Math.sin(la2));
  return [(lo2 * 180) / Math.PI, (la2 * 180) / Math.PI];
}

/* ---------- THE SPHERES ------------------------------------ */

const SPHERES = [
  { n: 0, name: "Home Ground", max: 0.25, range: "A couple of hours at most", gist: "The town, its fields and its own headlands. Back for the midday meal." },
  { n: 1, name: "Back by Dark", max: 0.45, range: "Up to half a day out", gist: "Out and back between dawn and dusk. A visit, not a journey." },
  { n: 2, name: "One Night Away", max: 1.3, range: "Half a day to a long day", gist: "Sleep there, come back tomorrow. Most of the bay." },
  { n: 3, name: "Two or Three Nights", max: 3, range: "Up to three days out", gist: "Business, a festival, a relative. Where the roads start to compete with the water." },
  { n: 4, name: "About a Week", max: 7, range: "Three to seven days", gist: "Rome, and with the wind behind you the far side of the sea." },
  { n: 5, name: "Weeks", max: Infinity, range: "More than a week", gist: "The sea world, in season only. Returns can take several times as long." },
];
const sphereOf = (days) => (days === null ? null : SPHERES.findIndex((s) => days <= s.max));

/* Dot colour runs continuously through the bracket colours, so the chart
   never implies a cliff at a bracket edge. The list keeps its groups. */
const hexToRgb = (h) => [1, 3, 5].map((i) => parseInt(h.slice(i, i + 2), 16));
const rgbToHex = (c) => "#" + c.map((v) => Math.round(Math.max(0, Math.min(255, v))).toString(16).padStart(2, "0")).join("");
function rampColour(days) {
  if (days === null) return T.chartDim;
  const s = sphereOf(days);
  const lo = s === 0 ? 0 : SPHERES[s - 1].max;
  const hi = s === 5 ? 21 : SPHERES[s].max;
  const t = Math.max(0, Math.min(1, (days - lo) / (hi - lo)));
  const a = hexToRgb(SPHERE_COLOUR[s]);
  const b = hexToRgb(s === 5 ? SPHERE_COLOUR_END : SPHERE_COLOUR[s + 1]);
  return rgbToHex(a.map((v, i) => v + (b[i] - v) * t));
}

/* ---------- THE NETWORK ------------------------------------
   One graph for everything. Nodes are the waypoints, edges are the
   legs of the candidate routes, and a place, a coast vertex and a point
   on the water are all costed by the same Dijkstra from the town. */

const NODE_KEYS = Object.keys(NODES);
const NODE_INDEX = Object.fromEntries(NODE_KEYS.map((k, i) => [k, i]));
const PLACE_BY_NODE = Object.fromEntries(Object.entries(PLACE_NODE).map(([p, n]) => [n, p]));

const EDGES = (() => {
  const seen = new Set();
  const out = [];
  for (const routes of Object.values(ROUTES)) {
    for (const route of routes) {
      for (const leg of route) {
        for (let i = 1; i < leg.p.length; i++) {
          const a = leg.p[i - 1];
          const b = leg.p[i];
          const key = `${a}|${b}|${leg.m}`;
          if (seen.has(key)) continue;
          seen.add(key);
          seen.add(`${b}|${a}|${leg.m}`);
          const km = nodeKm(a, b);
          out.push({ a, b, m: leg.m, km, wait: Boolean(leg.wait) && a === "PUTEOLI" });
          out.push({ a: b, b: a, m: leg.m, km, wait: Boolean(leg.wait) && b === "PUTEOLI" });
        }
      }
    }
  }
  return out;
})();
const ADJ = (() => {
  const adj = NODE_KEYS.map(() => []);
  EDGES.forEach((e, i) => adj[NODE_INDEX[e.a]].push(i));
  return adj;
})();

/* Node character, from the edges that touch it. */
const NODE_KIND = (() => {
  const sea = new Set();
  const land = new Set();
  for (const e of EDGES) (SEA_MODES.has(e.m) ? sea : land).add(e.a);
  return Object.fromEntries(NODE_KEYS.map((k) => [k, sea.has(k) && land.has(k) ? "port" : sea.has(k) ? "sea" : "land"]));
})();
/* Exposed water: a small boat from these nodes coasts rather than crosses. */
const EXPOSED = new Set(["CAMP_SEA", "GALLI_SEA", "POS_SEA", "AMALFI_SEA", "CETARA_SEA", "SAL_SEA", "PAE_SEA", "MIS_W", "PROCIDA_W", "CUM_SEA", "CAMP_LANDING"]);

const paceOf = (mode, persona) => persona.pace[mode] ?? PACE[mode].kmPerDay;

/* Cost of one edge for one traveller in one direction. Returns null if
   the edge is closed to them. */
function edgeCost(e, ctx) {
  const { season, persona, direction, forbid } = ctx;
  const sea = SEA_MODES.has(e.m);
  if (SEASONS[season].forbid.includes(e.m)) return null;
  if (!persona.allow({ m: e.m }, e.km)) return null;
  if (forbid && forbid.has(e.m)) return null;
  let days = e.km / paceOf(e.m, persona);
  if (direction === "back" && (e.m === "ship" || e.m === "shipcoast")) {
    const far = fromHomeKm(...N(e.a)) > fromHomeKm(...N(e.b)) ? e.a : e.b;
    days *= returnFactorAt(...N(far));
  }
  let wait = 0;
  if (e.wait) {
    // the wait is a property of what you board: a coaster is caught within the day, an open-sea ship is not
    wait = e.m === "shipcoast" ? persona.coasterWait : persona.shipWait;
    if (!isFinite(wait)) return null;
  }
  // Boarding a boat costs a tenant time spent finding a lift.
  if (sea && persona.boarding && NODE_KIND[e.a] !== "sea") days += persona.boarding;
  const w = (persona.weight && persona.weight[e.m]) || 1;
  return { days: days + wait, score: days * w + wait, wait };
}

const SHIP_MODES = new Set(["ship", "shipcoast"]);

/* Dijkstra over (node, vessel). State 0 is ashore, 1 aboard a coaster,
   2 aboard an open-sea ship. Either vessel is boarded only at Puteoli,
   after its own wait; changing vessel is a fresh boarding; you can step
   off at a port or town, never at a point in open water. */
const VESSEL = { shipcoast: 1, ship: 2 };
function dijkstra(ctx, by) {
  const n = NODE_KEYS.length;
  const S = 3 * n;
  const dist = new Float64Array(S).fill(Infinity);
  const days = new Float64Array(S).fill(Infinity);
  const prev = new Int32Array(S).fill(-1);
  const prevState = new Int32Array(S).fill(-1);
  const done = new Uint8Array(S);
  const s = NODE_INDEX.SURR;
  dist[s] = 0; days[s] = 0;
  for (;;) {
    let u = -1, best = Infinity;
    for (let i = 0; i < S; i++) if (!done[i] && dist[i] < best) { best = dist[i]; u = i; }
    if (u < 0) break;
    done[u] = 1;
    const vessel = Math.floor(u / n);
    const node = u % n;
    for (const ei of ADJ[node]) {
      const e = EDGES[ei];
      const v = VESSEL[e.m] || 0;
      let target, boarding = false;
      if (v) {
        if (vessel !== v) { if (e.a !== "PUTEOLI") continue; boarding = true; } // board, or change vessel, at Puteoli only
        target = NODE_INDEX[e.b] + v * n;
      } else {
        if (vessel && NODE_KIND[e.a] === "sea") continue; // no stepping off in open water
        target = NODE_INDEX[e.b];
      }
      const c = edgeCost({ ...e, wait: boarding }, ctx);
      if (!c) continue;
      const nd = dist[u] + (by === "days" ? c.days : c.score);
      if (nd < dist[target]) { dist[target] = nd; days[target] = days[u] + c.days; prev[target] = ei; prevState[target] = u; }
    }
  }
  const bestDist = new Float64Array(n), bestDays = new Float64Array(n), bestState = new Int32Array(n);
  for (let i = 0; i < n; i++) {
    let b = i;
    for (const st of [i + n, i + 2 * n]) if (dist[st] < dist[b]) b = st;
    bestDist[i] = dist[b]; bestDays[i] = days[b]; bestState[i] = b;
  }
  return { dist: bestDist, days: bestDays, state: bestState, prev, prevState, n };
}

/* The path to a node as legs: consecutive edges of one mode merged. */
function pathLegs(run, node, ctx) {
  const i = NODE_INDEX[node];
  if (!isFinite(run.dist[i])) return null;
  const edges = [];
  let st = run.state[i];
  while (run.prev[st] >= 0) {
    const from = run.prevState[st];
    edges.unshift({ e: EDGES[run.prev[st]], boarded: Math.floor(st / run.n) !== Math.floor(from / run.n) && Math.floor(st / run.n) > 0 });
    st = from;
  }
  const legs = [];
  for (const { e, boarded } of edges) {
    const c = edgeCost({ ...e, wait: boarded }, ctx);
    if (!c) return null;
    const last = legs[legs.length - 1];
    if (last && last.m === e.m && !boarded) { last.km += e.km; last.days += c.days; last.to = e.b; last.p.push(e.b); }
    else legs.push({ m: e.m, km: e.km, days: c.days, wait: c.wait, from: e.a, to: e.b, p: [e.a, e.b] });
  }
  return { legs, days: run.days[i], km: legs.reduce((t, l) => t + l.km, 0) };
}

const LAND_MODES = new Set(["track", "road"]);
const SEA_SET = new Set([...SEA_MODES]);

function derive(season, persona, direction) {
  const ctx = { season, persona, direction };
  const chosen = dijkstra(ctx, "score");
  const fastest = dijkstra(ctx, "days");
  const noSea = dijkstra({ ...ctx, forbid: SEA_SET }, "score");
  const noRoad = dijkstra({ ...ctx, forbid: LAND_MODES }, "score");
  const summerCtx = { season: "sailing", persona, direction };
  const summerRun = season !== "sailing" ? dijkstra(summerCtx, "score") : null;
  const out = {};
  for (const p of PLACES) {
    const node = PLACE_NODE[p.id];
    const best = pathLegs(chosen, node, ctx);
    const fast = pathLegs(fastest, node, ctx);
    let alt = null;
    if (best && fast && fast.days < best.days * 0.995 && fast.legs.map((l) => l.m).join() !== best.legs.map((l) => l.m).join()) {
      alt = { ...fast, why: "fastest" };
    } else if (best) {
      const usesSea = best.legs.some((l) => SEA_MODES.has(l.m));
      const other = pathLegs(usesSea ? noSea : noRoad, node, ctx);
      if (other && other.days <= best.days * 1.15 && other.legs.map((l) => l.m).join() !== best.legs.map((l) => l.m).join()) alt = { ...other, why: "tie" };
    }
    const summer = summerRun ? pathLegs(summerRun, node, summerCtx) : null;
    out[p.id] = {
      ...p,
      node,
      km: fromHomeKm(p.lon, p.lat),
      bearing: fromHomeBearing(p.lon, p.lat),
      days: best ? best.days : null,
      routeKm: best ? best.km : null,
      legs: best ? best.legs : [],
      alt,
      sphere: sphereOf(best ? best.days : null),
      shut: !best,
      harder: Boolean(best && summer && best.days > summer.days * 1.6),
      source: SOURCES[p.id] || [],
    };
  }
  return { places: out, nodeDays: chosen.days, nodeScore: chosen.dist };
}

/* ---------- COAST AND WATER -------------------------------- */

const FINE_BOX = { w: 13.45, e: 15.45, s: 40.15, n: 41.4 };
const inFineBox = (lon, lat) => lon > FINE_BOX.w && lon < FINE_BOX.e && lat > FINE_BOX.s && lat < FINE_BOX.n;
const NE_BOX = { w: -11, e: 40, s: 23, n: 59 };
const onClipEdge = (lon, lat) => Math.abs(lon - NE_BOX.w) < 0.05 || Math.abs(lon - NE_BOX.e) < 0.05 || Math.abs(lat - NE_BOX.s) < 0.05 || Math.abs(lat - NE_BOX.n) < 0.05;
/* The bay dataset was closed with a synthetic edge at lon 15.6 / lat 41.6. */
const onSyntheticEdge = (lon, lat) => Math.abs(lon - 15.6) < 0.01 || Math.abs(lat - 41.6) < 0.01;

/* Point in polygon, ray casting, on a flat lon/lat ring. */
function pip(lon, lat, r) {
  let inside = false;
  const n = r.length / 2;
  for (let i = 0, j = n - 1; i < n; j = i++) {
    const xi = r[2 * i], yi = r[2 * i + 1], xj = r[2 * j], yj = r[2 * j + 1];
    if (yi > lat !== yj > lat && lon < ((xj - xi) * (lat - yi)) / (yj - yi) + xi) inside = !inside;
  }
  return inside;
}
const FINE_BBOX = COAST_FINE.map((r) => { let w = 1e9, e = -1e9, s = 1e9, n = -1e9; for (let i = 0; i < r.length; i += 2) { w = Math.min(w, r[i]); e = Math.max(e, r[i]); s = Math.min(s, r[i + 1]); n = Math.max(n, r[i + 1]); } return { w, e, s, n }; });
function onLandFine(lon, lat) {
  for (let k = 0; k < COAST_FINE.length; k++) {
    const b = FINE_BBOX[k];
    if (lon < b.w || lon > b.e || lat < b.s || lat > b.n) continue;
    if (pip(lon, lat, COAST_FINE[k])) return true;
  }
  return false;
}
/* Does a straight water link touch land? Sampled, ends excluded. */
function crossesLand(a, b) {
  for (let t = 0.12; t < 0.9; t += 0.13) if (onLandFine(a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t)) return true;
  return false;
}

/* Distance from a point to the nearest vertex of a ring, in km. */
function nearRing(p, ring) {
  let best = Infinity;
  for (let i = 0; i < ring.length; i += 2) best = Math.min(best, kmBetween(p, [ring[i], ring[i + 1]]));
  return best;
}
/* An island vertex with no link of its own inherits the nearest linked
   vertex on the same island, plus the walk along the shore to it. */
function inheritIslandLinks(ring, links) {
  const n = ring.length / 2;
  const out = links.slice();
  for (let k = 0; k < n; k++) {
    if (out[k] && out[k].length) continue;
    let best = null, bestKm = Infinity;
    for (let j = 0; j < n; j++) {
      if (!links[j] || !links[j].length) continue;
      const km = kmBetween([ring[2 * k], ring[2 * k + 1]], [ring[2 * j], ring[2 * j + 1]]);
      if (km < bestKm) { bestKm = km; best = links[j]; }
    }
    out[k] = best ? best.map((l) => ({ ...l, walk: (l.walk || 0) + bestKm * 1.3 })) : [];
  }
  return out;
}

/* Persona-independent links from a point to the network, computed once. */
const SEA_NODES = NODE_KEYS.filter((k) => NODE_KIND[k] !== "land" && inFineBox(N(k)[0], N(k)[1]));
const LAND_NODES = NODE_KEYS.filter((k) => NODE_KIND[k] !== "sea" && inFineBox(N(k)[0], N(k)[1]));
function linksFor(lon, lat, island, seaOnly, ownRing) {
  const v = [lon, lat];
  const links = [];
  const seaCands = SEA_NODES.map((k) => ({ k, km: kmBetween(N(k), v) })).filter((c) => c.km < 14).sort((x, y) => x.km - y.km).slice(0, 7);
  for (const c of seaCands) {
    // a node on the same island (Marina Grande, the Ischia landing) is reached without crossing water
    const sameIsland = ownRing && (pip(N(c.k)[0], N(c.k)[1], ownRing) || nearRing(N(c.k), ownRing) < 0.4);
    if (sameIsland || !crossesLand(N(c.k), v)) links.push({ k: c.k, km: c.km, mode: sameIsland ? "foot" : EXPOSED.has(c.k) ? "coast" : "boat" });
  }
  if (!island && !seaOnly) {
    const landCands = LAND_NODES.map((k) => ({ k, km: kmBetween(N(k), v) })).filter((c) => c.km < 4.5).sort((x, y) => x.km - y.km).slice(0, 4);
    for (const c of landCands) links.push({ k: c.k, km: c.km * 1.3, mode: "foot" });
  }
  return links;
}
let FINE_LINKS = null;
function fineLinks() {
  if (FINE_LINKS) return FINE_LINKS;
  FINE_LINKS = COAST_FINE.map((r, ri) => {
    const out = new Array(r.length / 2);
    for (let k = 0; k < r.length / 2; k++) out[k] = onSyntheticEdge(r[2 * k], r[2 * k + 1]) ? [] : linksFor(r[2 * k], r[2 * k + 1], ri !== 0, false, ri !== 0 ? r : null);
    return ri !== 0 ? inheritIslandLinks(r, out) : out;
  });
  return FINE_LINKS;
}
const COARSE_MAINLAND = COAST_COARSE.reduce((bi, r, i, arr) => (r.length > arr[bi].length ? i : bi), 0);
let COARSE_BAY_LINKS = null; // links for the coarse vertices that lie inside the bay box
function coarseBayLinks() {
  if (COARSE_BAY_LINKS) return COARSE_BAY_LINKS;
  COARSE_BAY_LINKS = COAST_COARSE.map((r, ri) => {
    const out = new Array(r.length / 2);
    for (let k = 0; k < r.length / 2; k++) {
      const lon = r[2 * k], lat = r[2 * k + 1];
      out[k] = inFineBox(lon, lat) ? linksFor(lon, lat, ri !== COARSE_MAINLAND, false, ri !== COARSE_MAINLAND ? r : null) : null;
    }
    return ri !== COARSE_MAINLAND && out.some(Boolean) ? inheritIslandLinks(r, out.map((l) => l || [])) : out;
  });
  return COARSE_BAY_LINKS;
}

/* Cost of a point from its links, by the traveller's comfort score. */
function costFromLinks(links, model, persona) {
  if (!links || !links.length) return Infinity;
  const { nodeDays, nodeScore } = model;
  let bestScore = Infinity;
  let bestDays = Infinity;
  for (const l of links) {
    const i = NODE_INDEX[l.k];
    if (!isFinite(nodeDays[i])) continue;
    if (!persona.allow({ m: l.mode }, l.km)) continue;
    const extra = l.km / paceOf(l.mode, persona);
    const walk = l.walk ? (persona.allow({ m: "foot" }, l.walk) ? l.walk / paceOf("foot", persona) : Infinity) : 0;
    if (!isFinite(walk)) continue;
    const w = (persona.weight && persona.weight[l.mode]) || 1;
    const wf = (persona.weight && persona.weight.foot) || 1;
    const sc = nodeScore[i] + extra * w + walk * wf;
    if (sc < bestScore) { bestScore = sc; bestDays = nodeDays[i] + extra + walk; }
  }
  return bestDays;
}

const isAdriaticSide = (lon, lat) => lat > 39.8 && lat < 46 && lon > 12.3 + (45.5 - lat) * 0.618;
const viaMessina = (lon, lat) => isAdriaticSide(lon, lat) || (lat <= 39.8 && lat > 37.9 && lon > 16.1) || (lon > 18 && lat > 36);
const roundOtranto = (lon, lat) => isAdriaticSide(lon, lat) && (lat > 41 || lon > 17.8);
const ROAD_DETOUR = 1.12;

/* Beyond the bay: a ship from Puteoli, a coaster out of the bay, or the
   road from Stabiae, each costed from the network's own node costs. */
function coarseDays(lon, lat, isMainland, season, persona, direction, model) {
  if (onClipEdge(lon, lat)) return Infinity;
  const v = [lon, lat];
  const { nodeDays, nodeScore } = model;
  const W = (m) => (persona.weight && persona.weight[m]) || 1;
  const opts = [];
  const add = (start, parts) => {
    const i = NODE_INDEX[start];
    if (!isFinite(nodeDays[i])) return;
    let d = nodeDays[i], sc = nodeScore[i];
    for (const [days, mode] of parts) { if (!isFinite(days)) return; d += days; sc += days * W(mode); }
    opts.push([d, sc]);
  };
  const closed = (m) => SEASONS[season].forbid.includes(m);
  if (!closed("coast") && isMainland) {
    const b = fromHomeBearing(lon, lat);
    const exit = b > -85 && b <= 62 ? "MIS_CAPE" : "CAMP_SEA";
    const along = kmBetween(N(exit), v);
    if (persona.allow({ m: "coast" }, along)) add(exit, [[along / paceOf("coast", persona), "coast"]]);
  }
  if (!closed("ship") && isFinite(persona.shipWait) && persona.allow({ m: "ship" }, 1e9)) {
    let path = [N("PUTEOLI")];
    if (lon < -1 || (lat > 46 && lon < 12)) path.push(N("BONIFACIO"), N("BALEARIC_S"), N("GIBRALTAR"));
    else if (viaMessina(lon, lat)) { path.push(N("MESSINA")); if (roundOtranto(lon, lat)) path.push([18.6, 39.9]); if (lon > 26.5 && lat > 40.3) path.push([26.2, 40.0]); }
    path.push(v);
    let d = 0;
    for (let i = 1; i < path.length; i++) d += kmBetween(path[i - 1], path[i]);
    let shipDays = d / paceOf("ship", persona);
    if (direction === "back") shipDays *= returnFactorAt(lon, lat);
    add("PUTEOLI", [[persona.shipWait, "wait"], [shipDays, "ship"]]);
  }
  if (isMainland && persona.allow({ m: "road" }, 0)) add("STABIAE", [[(kmBetween(N("STABIAE"), v) * ROAD_DETOUR) / paceOf("road", persona), "road"]]);
  if (!opts.length) return Infinity;
  return opts.reduce((best, o) => (o[1] < best[1] ? o : best))[0];
}

function medianSmooth(a) {
  const n = a.length;
  if (n < 7) return a;
  const out = new Float64Array(n);
  const win = new Array(5);
  for (let i = 0; i < n; i++) { for (let j = -2; j <= 2; j++) win[j + 2] = a[(i + j + n) % n]; out[i] = win.slice().sort((x, y) => x - y)[2]; }
  return out;
}

/* ---------- ZOOM, PROJECTION, LAYOUT ----------------------- */

const ZOOMS = [
  { key: 0, name: "The peninsula", inner: 0, outer: 8, coast: "fine", note: "Your own ground. Everything here is walkable." },
  { key: 1, name: "A day's reach", inner: 3, outer: 16, coast: "fine", note: "Everything within sixteen kilometres. Positano is nine kilometres east." },
  { key: 2, name: "The bay", inner: 6, outer: 32, coast: "fine", note: "The Bay of Naples and the near end of the Gulf of Salerno." },
  { key: 3, name: "The region", inner: 8, outer: 65, coast: "fine", note: "The whole bay, the Phlegraean shore to the west, and the first towns beyond the mountains." },
  { key: 4, name: "Italy", inner: 45, outer: 230, coast: "coarse", note: "Campania to Rome. Beneventum is the one place in this frame that no boat can help you reach." },
  { key: 5, name: "The sea", inner: 180, outer: 1900, coast: "coarse", note: "The Mediterranean. Carthage and Massilia are as near as Rome." },
];
const PROJECTIONS = { distance: { label: "Distance", unit: "km" }, time: { label: "Travel time", unit: "days" } };

const W = 660, H = 660, CX = W / 2, CY = H / 2, PAD = 62;
const MAX_R = Math.min(CX, CY) - PAD;
const CLIP_R = MAX_R + 26;
const FAR = CLIP_R * 1.6;

const NICE = [0.25, 0.5, 1, 2, 3, 5, 7, 10, 14, 20, 25, 30, 50, 75, 100, 150, 200, 300, 500, 750, 1000, 1500, 2000];
function ringLabel(v, unit) {
  if (unit === "km") return `${v} km`;
  if (v === 0.25) return "a quarter day";
  if (v === 0.5) return "half a day";
  if (v === 1) return "1 day";
  return `${v} days`;
}
function niceRings(maxUnit) {
  const fits = NICE.filter((n) => n <= maxUnit * 0.98 && n >= maxUnit * 0.06);
  if (fits.length <= 4) return fits;
  const out = [];
  for (let i = 0; i < 4; i++) out.push(fits[Math.round((i * (fits.length - 1)) / 3)]);
  return [...new Set(out)];
}

const STEP = 15, HALF_W = 82;
function placeLabels(pts) {
  const taken = [];
  const put = {};
  const dropped = new Set();
  const clash = (x, y) => taken.some((q) => Math.abs(q.y - y) < STEP && Math.abs(q.x - x) < HALF_W);
  const tries = [];
  for (const dy of [0, STEP, -STEP, 2 * STEP, -2 * STEP, 3 * STEP]) tries.push({ flip: false, dy }, { flip: true, dy });
  Object.entries(pts).sort((a, b) => a[1].y - b[1].y).forEach(([id, p]) => {
    const hit = tries.find((t) => !clash(p.x + (t.flip ? -HALF_W / 2 : HALF_W / 2), p.y + t.dy));
    if (!hit) { dropped.add(id); return; }
    put[id] = hit;
    taken.push({ x: p.x + (hit.flip ? -HALF_W / 2 : HALF_W / 2), y: p.y + hit.dy });
  });
  return { put, dropped };
}

function polar(bearing, r) { const a = rad(bearing - 90); return { x: CX + r * Math.cos(a), y: CY + r * Math.sin(a) }; }

function layout(projection, places) {
  const isTime = projection === "time";
  const reachable = places.filter((p) => p.days !== null);
  const max = isTime ? Math.max(...reachable.map((p) => p.days), 0.2) : Math.max(...places.map((p) => p.km), 1);
  const ringScale = isTime
    ? (d) => (d === null || !isFinite(d) ? FAR : (Math.sqrt(d) / Math.sqrt(max)) * MAX_R)
    : (km) => (km / max) * MAX_R;
  const pts = {};
  places.forEach((p) => { if (isTime && p.days === null) return; pts[p.id] = polar(p.bearing, ringScale(isTime ? p.days : p.km)); });
  return { pts, ...placeLabels(pts), ringScale, unitMax: max };
}

function projectCoast(rings, isFine, projection, ringScale, season, persona, direction, model) {
  const isTime = projection === "time";
  const links = isFine ? fineLinks() : coarseBayLinks();
  return rings.map((r, ri) => {
    const isIsland = isFine ? ri !== 0 : ri !== COARSE_MAINLAND;
    const n = r.length / 2;
    let days = null;
    if (isTime) {
      days = new Float64Array(n);
      for (let k = 0; k < n; k++) {
        const lon = r[2 * k], lat = r[2 * k + 1];
        const viaLinks = links[ri][k] && links[ri][k].length ? costFromLinks(links[ri][k], model, persona) : Infinity;
        days[k] = isFinite(viaLinks) ? viaLinks : onSyntheticEdge(lon, lat) ? Infinity : coarseDays(lon, lat, !isIsland, season, persona, direction, model);
      }
      days = medianSmooth(days);
    }
    // Two consecutive vertices far apart in bearing (the clip edges, mostly)
    // would draw a chord across the chart; follow the arc between them
    // instead. The insertion depends on geometry only, so both
    // projections produce the same point count and can morph.
    const bear = new Float64Array(n);
    const rad_ = new Float64Array(n);
    for (let k = 0; k < n; k++) {
      const lon = r[2 * k], lat = r[2 * k + 1];
      bear[k] = fromHomeBearing(lon, lat);
      rad_[k] = isTime ? (isFinite(days[k]) ? Math.min(ringScale(days[k]), FAR) : FAR) : Math.min(ringScale(fromHomeKm(lon, lat)), FAR);
    }
    const pts = [];
    for (let k = 0; k < n; k++) {
      const p = polar(bear[k], rad_[k]);
      pts.push(p.x, p.y);
      const j = (k + 1) % n;
      let gap = bear[j] - bear[k];
      while (gap > 180) gap -= 360;
      while (gap < -180) gap += 360;
      if (Math.abs(gap) > 25) {
        const steps = Math.ceil(Math.abs(gap) / 25);
        for (let i = 1; i < steps; i++) {
          const t = i / steps;
          const q = polar(bear[k] + gap * t, rad_[k] + (rad_[j] - rad_[k]) * t);
          pts.push(q.x, q.y);
        }
      }
    }
    return Float64Array.from(pts);
  });
}

/* Water samples on a polar grid from the landing, with their links to
   the network, computed once. Cost per traveller comes from the model. */
const SEA_BEARINGS = 72;
