function Coastline({ rings, reduceMotion }) {
  const refs = useRef([]);
  useMorph(rings, reduceMotion, (cur) => cur.forEach((r, i) => { const el = refs.current[i]; if (el) el.setAttribute("d", toPath(r)); }));
  return <g className="land" clipPath="url(#chart-clip)">{rings.map((_, i) => <path key={`${rings.length}-${i}`} ref={(el) => { refs.current[i] = el; }} />)}</g>;
}

function RouteLines({ routes, reduceMotion }) {
  // routes: [{ key, m, alt, pts: Float64Array }]
  const refs = useRef([]);
  const targets = useMemo(() => routes.map((r) => r.pts), [routes]);
  useMorph(targets, reduceMotion, (cur) => cur.forEach((arr, i) => { const el = refs.current[i]; if (!el) return; let s = ""; for (let j = 0; j < arr.length; j += 2) s += arr[j].toFixed(1) + "," + arr[j + 1].toFixed(1) + " "; el.setAttribute("points", s); }));
  return (
    <g className="routes" clipPath="url(#chart-clip)">
      {routes.map((r, i) => (
        <polyline key={`${routes.length}-${i}`} ref={(el) => { refs.current[i] = el; }} className={"route-line" + (r.alt ? " is-alt" : "")} stroke={ROUTE_COLOUR[r.m]} strokeDasharray={ROUTE_DASH[r.m]} />
      ))}
    </g>
  );
}

